  }
  addRowTools();
  document.addEventListener('click', function(e){
    if (!EDIT) return;
    var d = e.target.closest('[data-rowdel]'), a = e.target.closest('[data-rowadd]');
    var tr = (d || a) && (d || a).closest('tr'); if (!tr) return;
