// Applies the 11 MM consultant objections (2026-10-27 trial) to the ZMM000 state files.
import { copyFileSync, existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const ST = process.argv[2];
const rd = (f) => JSON.parse(readFileSync(join(ST, f), 'utf8'));
const wr = (f, o) => writeFileSync(join(ST, f), JSON.stringify(o, null, 1));
const files = ['step4.json', 'step6.MM.json', ...[1, 2, 3, 4, 5, 6, 7, 8].map(k => `step5.part-${k}.json`)];
for (const f of files) if (!existsSync(join(ST, `${f}.bak-objections`))) copyFileSync(join(ST, f), join(ST, `${f}.bak-objections`));

const s4 = rd('step4.json');
const s6 = rd('step6.MM.json');
const parts = [1, 2, 3, 4, 5, 6, 7, 8].map(k => [`step5.part-${k}.json`, rd(`step5.part-${k}.json`)]);
const row = (c) => s4.rows.find(r => r.code === c);
const taskOf = (c) => { for (const [, p] of parts) { const t = p.tasks.find(x => x.code === c); if (t) return t; } return null; };
const log = [];

function renameCode(from, to) {
  row(from).code = to;
  for (const [, p] of parts) for (const t of p.tasks) if (t.code === from) t.code = to;
  for (const k of ['labels', 'owners', 'conversion', 'std_sheets', 'objections']) for (const x of s6[k] || []) if (x.code === from) x.code = to;
  const fix = (l) => (typeof l === 'string' ? (l === from ? to : l) : (l.code === from ? { ...l, code: to } : l));
  for (const [, p] of parts) for (const t of p.tasks) if (t.task?.links) t.task.links = t.task.links.map(fix);
  log.push(`renamed ${from} → ${to}`);
}
const drop = (list, names) => (list || []).filter(o => !names.includes(typeof o === 'string' ? o.replace(/ \(.*$/, '') : o.name));
const setLabel = (c, label) => { row(c).label = label; s6.labels = (s6.labels || []).filter(x => !(x.code === c && x.label)); log.push(`label ${c}`); };

// 1. 1.1.3.3 → under 1.3.1, owner trade
renameCode('1.1.3.3', '1.3.1.7');
Object.assign(row('1.3.1.7'), { owner: 'trade', ownerEstimated: true });
s6.owners = (s6.owners || []).filter(x => x.code !== '1.3.1.7');
// 2. 1.1.3.4: backbone MM.1.3.1, no MEK1/MEK2, link to 1.3.1.5
Object.assign(row('1.1.3.4'), { backbone: 'MM.1.3.1', tcodes: row('1.1.3.4').tcodes.filter(t => !['MEK1', 'MEK2'].includes(t)) });
{ const t = taskOf('1.1.3.4'); if (t) t.task.links = [...new Set([...(t.task.links || []), '1.3.1.5'])]; }
log.push('1.1.3.4 backbone/tcodes/link');
// 3. 1.2.1.3: no MD01/MD04, label, backbone MM.2.1.1
Object.assign(row('1.2.1.3'), { backbone: 'MM.2.1.1', tcodes: row('1.2.1.3').tcodes.filter(t => !['MD01', 'MD04'].includes(t)) });
setLabel('1.2.1.3', '예비품 MRP 요청 등록 및 구매요청 전환');
// 4. 1.2.2.2 → under 1.2.1, no ME59N
renameCode('1.2.2.2', '1.2.1.4');
row('1.2.1.4').tcodes = row('1.2.1.4').tcodes.filter(t => t !== 'ME59N');
// 5. 1.4.4.1: label, drop ZMMT01230/01240
setLabel('1.4.4.1', 'PRT 출고/저장위치 이동/초기 재고 처리');
row('1.4.4.1').objects = drop(row('1.4.4.1').objects, ['ZMMT01230', 'ZMMT01240']);
{ const t = taskOf('1.4.4.1'); if (t) { t.task.objects = drop(t.task.objects, ['ZMMT01230', 'ZMMT01240']); if (t.row_patch?.objects) t.row_patch.objects = drop(t.row_patch.objects, ['ZMMT01230', 'ZMMT01240']); } }
// 6. 1.3.2.4: label, cross_module without ZMMM21260
setLabel('1.3.2.4', '법인간 PO 수량 조정(출고 수량 기준)');
for (const c of s4.cross_module) if (/ZMMM21260/.test(c.object)) c.object = c.object.replace(/\s*\/\s*ZMMM21260/, '');
// 7. new batch L4 under 1.3.5
s4.rows.push({ code: '1.3.5.5', level: 4, label: '재고공유 주문 배치 처리(이벤트 잡)', desc: '1.3.5.3 / 1.3.5.4가 쌓은 요청 행(ZMMT70190~70220)을 이벤트 ZPANHK_BG_JOB01~04로 기동된 배치 잡이 판매오더·구매오더로 만듦.',
  kind: 'cbo', system: 'sap', tcodes: [], objects: ['ZMMT70190', 'ZMMT70200', 'ZMMT70210', 'ZMMT70220'], owner: 'trade', ownerEstimated: true, usage: 'unknown' });
parts[5][1].tasks.push({ code: '1.3.5.5', task: { definition: '요청 테이블의 판매오더·구매오더 생성 요청을 배치 잡이 처리함(추정).', timing: '이벤트 기동 배치(ZPANHK_BG_JOB01~04)',
  links: ['1.3.5.3', '1.3.5.4'], tbd: ['이벤트 ZPANHK_BG_JOB01~04에 걸린 잡 프로그램 확인 필요 (SM37 / SM64)', '잡 프로그램은 ZMM000 범위 밖일 수 있음'] } });
s4.open_questions.push('이벤트 ZPANHK_BG_JOB01~04로 기동되는 재고공유 주문 배치 잡 프로그램이 무엇인지 확인해야 함 (1.3.5.5).');
log.push('added 1.3.5.5');
// 8. 1.4.2.2: desc + cross_module CO text
row('1.4.2.2').desc = '예약 목록을 승인·출력·메일 발송함. 승인은 ZMMT42140 플래그와 리더 권한으로 함. 오더 예산·가용예산은 출력물에 표시만 하고 승인을 막지 않음.';
for (const c of s4.cross_module) if (c.to === 'CO' && /ZCO_FM_BUDGET_CHECK/.test(c.object)) c.desc = '예약 출력물에 오더 예산과 가용예산을 표시함(승인 통제 아님).';
log.push('1.4.2.2 desc');
// 9. 1.4.1.3 → not_evidenced
s4.rows = s4.rows.filter(r => r.code !== '1.4.1.3');
s6.std_sheets = (s6.std_sheets || []).filter(x => x.code !== '1.4.1.3');
s4.not_evidenced.push({ backbone: 'MM.3.1.3', label: '품질검사 재고 해제', reason: 'QM이 활성 모듈이 아니고 사용 실적·CBO 근거가 없음. ST03N으로 QA11/QA32 사용 여부 확인 필요.' });
log.push('1.4.1.3 → not_evidenced');
// 10. 1.6.1.3 launcher
row('1.6.1.3').remark = '탐색 메뉴(자체 로직 없음) — 전환 공수는 호출 대상별로 산정';
log.push('1.6.1.3 remark');
// 11. 1.7.2.2 without ZMM_RFC_MBEW
row('1.7.2.2').objects = drop(row('1.7.2.2').objects, ['ZMM_RFC_MBEW']);
{ const t = taskOf('1.7.2.2'); if (t) { t.task.objects = drop(t.task.objects, ['ZMM_RFC_MBEW']); t.task.interfaces = (t.task.interfaces || []).filter(i => i.system !== 'sap_rfc'); } }
log.push('1.7.2.2 RFC removed');

// document order: sort rows by numeric code segments
const key = (c) => c.split('.').map(n => n.padStart(4, '0')).join('.');
s4.rows.sort((a, b) => (key(a.code) < key(b.code) ? -1 : 1));
s6.objections_applied = (s6.objections || []).length; s6.objections = [];
wr('step4.json', s4); wr('step6.MM.json', s6); for (const [f, p] of parts) wr(f, p);
console.log(log.join('\n'));

