  const rows = [
    ['Invented BPH'], ['L1 ID', 'L1 Desc.(KO)', 'L2 ID', 'L2 Desc.(KO)', 'L3 ID', 'L3 Desc.(KO)', 'L4 ID', 'L4 Desc.(KO)', 'L4 Desc.(EN)', 'To-Be System', 'Variant ID', 'Variant Desc'],
