    expect(rc.modelOnly.map((x: any) => x.code)).toEqual(['1.1.2.1']);
    const html = renderProcessHtml({ ...MODEL, reconcile: { source: 'bph.xlsx', ...rc } }, { version: '1.0', date: 'd' });
    expect(html).toContain('id="bphrc"');
    expect(html).toContain('BPH에만 있음');
  });
});

